/// <reference path="./.sst/platform/config.d.ts" />

/**
 * InvAI on AWS. Repos are siblings of this one: ../invai-backend, ../invai-imaging,
 * ../invai-web, ../invai-floor. Written and typechecked against the installed sst@4.17.1
 * (component sources under `.sst/platform/src/components`, generated by `sst install`) --
 * check that directory before changing component options rather than guessing from docs
 * written for other SST versions.
 *
 * `sst deploy` needs AWS credentials and the owner's go-ahead per stage. Typecheck with
 * `pnpm typecheck`; nothing here has been deployed yet (T-24-1). The owner inputs this file
 * reads (domain, secrets) are listed in README.md "AWS (SST)".
 *
 * Stages: `production`, `staging`, and `demo` (the only stage that may boot on mock providers,
 * `ALLOW_MOCKS=true`). Any other stage name behaves like staging.
 */
export default $config({
  app(input) {
    return {
      name: "invai",
      home: "aws",
      removal: input?.stage === "production" ? "retain" : "remove",
      protect: input?.stage === "production",
    };
  },
  async run() {
    // Same helpers the web/floor builds use for their CSP, so the header CloudFront sends pins
    // the same origins, derived the same way (T-12-5 review r1, B-190).
    const webCsp = await import("../invai-web/src/lib/build/csp");
    const floorCsp = await import("../invai-floor/src/lib/build/csp");

    const stage = $app.stage;
    const isProd = stage === "production";
    const isDemo = stage === "demo";
    const region = aws.getRegionOutput().region;

    // ---- Domain (owner input) -----------------------------------------------------------
    // One registrable domain for every stage, so web, floor and api are same-site and Better
    // Auth's cookies work (B-57). Read from the deploy environment, never hard-coded:
    // `INVAI_DOMAIN=example.com sst deploy --stage staging`. Its Route 53 hosted zone must exist
    // in this account; SST creates the ACM certificates and DNS records in it.
    const domain = (process.env.INVAI_DOMAIN ?? "").trim().toLowerCase();
    if (!/^(?!-)[a-z0-9-]{1,63}(\.[a-z0-9-]{1,63})+$/.test(domain)) {
      throw new Error(
        "Set INVAI_DOMAIN to the registrable domain InvAI runs on (for example " +
          'INVAI_DOMAIN=invai.example). Stage hosts are "app|floor|api.<domain>" in ' +
          'production and "app|floor|api.<stage>.<domain>" elsewhere.',
      );
    }
    const host = (name: string) => (isProd ? `${name}.${domain}` : `${name}.${stage}.${domain}`);
    const apiHost = host("api");
    const webHost = host("app");
    const floorHost = host("floor");
    const apiOrigin = `https://${apiHost}`;
    const webOrigin = `https://${webHost}`;
    const floorOrigin = `https://${floorHost}`;
    const mailDomain = isProd ? domain : `${stage}.${domain}`;

    // ---- Network --------------------------------------------------------------------------
    // Cheap NAT instance instead of NAT gateways (research 11 §7.1). RDS and Valkey sit in the
    // private subnets (component default). ECS tasks run in the private subnets too (the
    // cluster below), reaching the internet through the NAT instance; only the ALB is public.
    const vpc = new sst.aws.Vpc("Vpc", { nat: "ec2" });

    // S3 gateway endpoint (B-107): S3 traffic from the private subnets skips the NAT instance
    // (free, and no NAT bandwidth limit for multi-GB gang sheets).
    new aws.ec2.VpcEndpoint("S3Endpoint", {
      vpcId: vpc.id,
      serviceName: $interpolate`com.amazonaws.${region}.s3`,
      vpcEndpointType: "Gateway",
      routeTableIds: $output(vpc.nodes.privateRouteTables).apply((tables) =>
        tables.map((t) => t.id),
      ),
    });

    // ---- Secrets (owner input, `sst secret set <Name> <value> --stage <stage>`) ------------
    // Every key in invai-backend `src/env.ts` PRODUCTION_KEYS is here (B-77) plus the core
    // secrets. No placeholder outside `demo`, so a deploy fails loudly while one is unset. On
    // `demo` the provider keys default to a single space: the backend trims it to "unset" and
    // runs that provider's mock (SSM rejects an empty parameter value).
    const required = (name: string) => new sst.Secret(name);
    const providerKey = (name: string) => new sst.Secret(name, isDemo ? " " : undefined);
    const secret = {
      BETTER_AUTH_SECRET: required("BetterAuthSecret"),
      // Separate from BETTER_AUTH_SECRET on purpose: rotating the auth secret must not also
      // invalidate every floor PIN hash and station token (env.ts falls back otherwise).
      FLOOR_TOKEN_SECRET: required("FloorTokenSecret"),
      FIELD_ENCRYPTION_KEY: required("FieldEncryptionKey"),
      IMAGING_SHARED_SECRET: required("ImagingSharedSecret"),
      // Password of the RLS-enforced `invai_app` role; bootstrap-cli creates/updates the role
      // from DATABASE_URL (T-24-2), RDS Proxy authenticates it in production.
      APP_DB_PASSWORD: required("AppDbPassword"),
      ANTHROPIC_API_KEY: providerKey("AnthropicApiKey"),
      EASYPOST_API_KEY: providerKey("EasyPostApiKey"),
      EASYPOST_WEBHOOK_SECRET: providerKey("EasyPostWebhookSecret"),
      SHOPIFY_API_KEY: providerKey("ShopifyApiKey"),
      SHOPIFY_API_SECRET: providerKey("ShopifyApiSecret"),
      STRIPE_SECRET_KEY: providerKey("StripeSecretKey"),
      STRIPE_WEBHOOK_SECRET: providerKey("StripeWebhookSecret"),
      // smtps://<SES SMTP user>:<password>@email-smtp.<region>.amazonaws.com:465 (B-58).
      SMTP_URL: providerKey("SmtpUrl"),
    };

    // ---- Postgres ------------------------------------------------------------------------
    const appDbUser = "invai_app";
    const db = new sst.aws.Postgres("Db", {
      vpc,
      version: "17",
      username: "invai",
      instance: isProd ? "t4g.medium" : "t4g.small",
      storage: isProd ? "100 GB" : "20 GB",
      // Pools connections from api tasks that scale out. The extra credential lets the proxy
      // authenticate `invai_app`, the role the api and worker use (B-01).
      proxy: isProd
        ? { credentials: [{ username: appDbUser, password: secret.APP_DB_PASSWORD.value }] }
        : false,
      transform: {
        // B-74: TLS required for every connection (the component default is force_ssl 0).
        parameterGroup: (args) => {
          args.parameters = [
            { name: "rds.force_ssl", value: "1" },
            { name: "rds.logical_replication", value: "1", applyMethod: "pending-reboot" },
          ];
        },
        // Research 11 §7.1 / B-74: the component defaults to 7-day backups, no deletion
        // protection and no final snapshot.
        instance: (args) => {
          args.backupRetentionPeriod = isProd ? 35 : 14;
          args.deletionProtection = isProd;
          args.skipFinalSnapshot = !isProd;
          args.finalSnapshotIdentifier = isProd ? `invai-${stage}-db-final` : undefined;
          args.copyTagsToSnapshot = true;
          args.caCertIdentifier = "rds-ca-rsa2048-g1";
        },
      },
    });

    // node-postgres treats sslmode=require as verify-full anyway (pg-connection-string 2.14), so
    // say verify-full. The RDS CA bundle is added to Node's trust store by NODE_EXTRA_CA_CERTS
    // (the backend image ships it, T-24-3); the RDS Proxy cert chains to Amazon's public roots.
    const pgUrl = (
      user: $util.Input<string>,
      password: $util.Input<string>,
      dbHost: $util.Input<string>,
    ) =>
      $interpolate`postgres://${user}:${$output(password).apply(encodeURIComponent)}@${dbHost}:${db.port}/${db.database}?sslmode=verify-full`;
    // App role (RLS enforced) through the proxy in production, direct elsewhere.
    const databaseUrl = pgUrl(appDbUser, secret.APP_DB_PASSWORD.value, db.host);
    // Owner role for migrations, the outbox relay and cross-tenant jobs: always direct to the
    // instance (advisory locks and session settings must not go through the proxy).
    const dbInstance = db.nodes.instance;
    if (!dbInstance) throw new Error("Db has no RDS instance (sst dev mode is not supported here)");
    const migrationDatabaseUrl = pgUrl(db.username, db.password, dbInstance.address);

    // ---- Valkey --------------------------------------------------------------------------
    // B-02: BullMQ with a plain ioredis client needs cluster mode OFF (the component defaults to
    // on) and noeviction (evicted job keys are lost jobs).
    const redis = new sst.aws.Redis("Redis", {
      vpc,
      engine: "valkey",
      instance: isProd ? "t4g.small" : "t4g.micro",
      cluster: false,
      parameters: { "maxmemory-policy": "noeviction" },
    });
    // TLS + AUTH are required by the component. The generated token can contain `#`, `&`, `$`,
    // so it is percent-encoded (ioredis decodes it).
    const redisUrl = $interpolate`rediss://${redis.username}:${$output(redis.password).apply((p) => encodeURIComponent(p ?? ""))}@${redis.host}:${redis.port}`;

    // ---- Files (S3) ----------------------------------------------------------------------
    // Keys are `{companyId}/{kind}/{yyyy}/{mm}/{uuid}.{ext}` (invai-backend src/lib/s3.ts), so a
    // prefix lifecycle rule can't select a kind (the old `sheets/` and `raw/` rules matched
    // nothing). Per-kind retention is the app's PII purge job (orders/jobs.ts). The bucket keeps
    // versions for 7 days so an accidental delete is recoverable, then expires them so a purge
    // really removes PII within a week (B-73).
    const files = new sst.aws.Bucket("Files", {
      versioning: true,
      cors: {
        // Browser PUTs to presigned URLs (web uploads) and GETs of signed images.
        allowOrigins: [webOrigin, floorOrigin],
        allowMethods: ["GET", "HEAD", "PUT"],
        allowHeaders: ["*"],
        exposeHeaders: ["ETag"],
        maxAge: "1 hour",
      },
      lifecycle: [{ id: "housekeeping" }],
      transform: {
        bucket: (args) => {
          args.forceDestroy = !isProd;
        },
        lifecycle: (args) => {
          args.rules = [
            {
              id: "housekeeping",
              status: "Enabled",
              filter: {},
              abortIncompleteMultipartUpload: { daysAfterInitiation: 1 },
              noncurrentVersionExpiration: { noncurrentDays: 7 },
              expiration: { expiredObjectDeleteMarker: true },
            },
          ];
        },
      },
    });
    // Virtual-hosted presign host, pinned so the CSP and the backend agree on one origin.
    const s3PublicEndpoint = $interpolate`https://s3.${region}.amazonaws.com`;
    const s3Origin = $interpolate`https://${files.name}.s3.${region}.amazonaws.com`;

    // ---- KMS key for field encryption (consumed by T-24-2's kms provider) ----------------
    const fieldEncryptionKmsKey = new aws.kms.Key("FieldEncryptionKey", {
      description: `InvAI ${stage} field-level encryption for buyer PII and OAuth tokens`,
      enableKeyRotation: true,
      deletionWindowInDays: 30,
    });
    new aws.kms.Alias("FieldEncryptionKeyAlias", {
      name: `alias/invai-${stage}-field-encryption`,
      targetKeyId: fieldEncryptionKmsKey.keyId,
    });

    // ---- Email (SES) ---------------------------------------------------------------------
    // Sender domain per stage (one SES identity per domain per account). SST writes the DKIM,
    // DMARC and custom MAIL FROM records into Route 53. The account starts in the SES sandbox
    // until the owner requests production access (B-58).
    new sst.aws.Email("Email", {
      sender: mailDomain,
      dns: sst.aws.dns(),
      dmarc: "v=DMARC1; p=quarantine; adkim=s; aspf=s;",
      mailFrom: { domain: `mail.${mailDomain}` },
    });

    // ---- Secrets to ECS via SSM --------------------------------------------------------
    // Values reach the containers through SSM SecureString parameters (`ssm` below), so they
    // are never plaintext in the task definition, and secrets are not `link`ed (a link would
    // put them in the environment as SST_RESOURCE_*).
    const ssmParams: Record<string, $util.Output<string>> = {};
    const toSsm = (name: string, value: $util.Input<string>) => {
      ssmParams[name] = new aws.ssm.Parameter(`Ssm${name}`, {
        name: `/invai/${stage}/${name}`,
        type: "SecureString",
        value,
      }).arn;
      return ssmParams[name];
    };
    toSsm("DATABASE_URL", databaseUrl);
    toSsm("MIGRATION_DATABASE_URL", migrationDatabaseUrl);
    toSsm("REDIS_URL", redisUrl);
    for (const [envName, s] of Object.entries(secret)) {
      if (envName !== "APP_DB_PASSWORD") toSsm(envName, s.value);
    }
    const pick = (...names: string[]) =>
      Object.fromEntries(names.map((n) => [n, ssmParams[n]])) as Record<
        string,
        $util.Output<string>
      >;
    const backendSsm = pick(
      "DATABASE_URL",
      "MIGRATION_DATABASE_URL",
      "REDIS_URL",
      "BETTER_AUTH_SECRET",
      "FLOOR_TOKEN_SECRET",
      "FIELD_ENCRYPTION_KEY",
      "IMAGING_SHARED_SECRET",
      "ANTHROPIC_API_KEY",
      "EASYPOST_API_KEY",
      "EASYPOST_WEBHOOK_SECRET",
      "SHOPIFY_API_KEY",
      "SHOPIFY_API_SECRET",
      "STRIPE_SECRET_KEY",
      "STRIPE_WEBHOOK_SECRET",
      "SMTP_URL",
    );

    // ---- ECS -----------------------------------------------------------------------------
    // Tasks in the private subnets (no public IP); the ALB in the public ones.
    const cluster = new sst.aws.Cluster("Cluster", {
      vpc: {
        id: vpc.id,
        securityGroups: vpc.securityGroups,
        containerSubnets: vpc.privateSubnets,
        loadBalancerSubnets: vpc.publicSubnets,
        cloudmapNamespaceId: vpc.nodes.cloudmapNamespace.id,
        cloudmapNamespaceName: vpc.nodes.cloudmapNamespace.name,
      },
    });

    // Graceful drain (B-16, wave 9 deferral): ECS waits this long after SIGTERM before SIGKILL.
    // The api drains HTTP and the worker drains BullMQ within 20-30 s, so 45 s leaves margin
    // (the ECS default is 30 s; the Fargate maximum is 120 s).
    const STOP_TIMEOUT_S = 45;
    const withStopTimeout = (args: aws.ecs.TaskDefinitionArgs): undefined => {
      args.containerDefinitions = $output(args.containerDefinitions).apply((json) =>
        JSON.stringify(
          (JSON.parse(json) as Record<string, unknown>[]).map((c) => ({
            ...c,
            stopTimeout: STOP_TIMEOUT_S,
          })),
        ),
      );
      return undefined;
    };

    // S-45: SST's stock execution role reads SSM and Secrets Manager on "*". Every ECS task here
    // gets the same replacement inline policy instead: SSM reads of its own stage's
    // `/invai/<stage>/*` only, no Secrets Manager (unused). The managed
    // AmazonECSTaskExecutionRolePolicy (ECR pull, logs) stays. Helper: infra/execution-role.ts.
    const { executionRolePolicy } = await import("./infra/execution-role");
    const executionRole = {
      inlinePolicies: [
        {
          name: "inline",
          policy: $resolve([
            aws.getPartitionOutput().partition,
            region,
            aws.getCallerIdentityOutput().accountId,
          ]).apply(([partition, regionName, accountId]) =>
            JSON.stringify(
              executionRolePolicy({ partition, region: regionName, accountId, stage }),
            ),
          ),
        },
      ],
    };

    // Imaging: internal only, no load balancer. Reached through Cloud Map service discovery
    // (`imaging.service`); `imaging.url` throws for a service with no public port (B-57).
    const imaging = new sst.aws.Service("Imaging", {
      cluster,
      architecture: "arm64",
      image: { context: "../invai-imaging" },
      cpu: "2 vCPU",
      memory: "8 GB",
      storage: "40 GB",
      link: [files],
      environment: {
        IMAGING_ENV: "production",
        IMAGING_DEV_ENDPOINTS: "false",
        STORAGE: "s3",
        S3_BUCKET: files.name,
        S3_REGION: region,
        // Real S3 through the task role: blank endpoint and keys override imaging's MinIO
        // defaults (app/config.py; `or None` turns "" into boto3's default chain).
        S3_ENDPOINT: "",
        S3_ACCESS_KEY_ID: "",
        S3_SECRET_ACCESS_KEY: "",
        S3_CREATE_BUCKET: "false",
      },
      ssm: pick("IMAGING_SHARED_SECRET"),
      health: {
        command: [
          "CMD",
          ".venv/bin/python",
          "-c",
          "import urllib.request; urllib.request.urlopen('http://127.0.0.1:8000/health', timeout=4)",
        ],
        startPeriod: "30 seconds",
      },
      scaling: { min: 1, max: isProd ? 3 : 1, cpuUtilization: 70 },
      transform: { taskDefinition: withStopTimeout, executionRole },
    });
    const imagingUrl = $interpolate`http://${imaging.service}:8000`;

    // Build context is the workspace root: backend links `@invai/contracts` via
    // `link:../invai-contracts` (see invai-infra/local/docker-compose.yml `full`).
    const backendImage = { context: "..", dockerfile: "invai-backend/Dockerfile" } as const;

    const backendEnvironment = {
      NODE_ENV: "production",
      BETTER_AUTH_URL: apiOrigin,
      WEB_ORIGIN: webOrigin,
      FLOOR_ORIGIN: floorOrigin,
      IMAGING_URL: imagingUrl,
      S3_BUCKET: files.name,
      S3_REGION: region,
      S3_FORCE_PATH_STYLE: "false",
      S3_PUBLIC_ENDPOINT: s3PublicEndpoint,
      MAIL_FROM: `InvAI <no-reply@${mailDomain}>`,
      // T-24-2's KMS envelope provider; the static FIELD_ENCRYPTION_KEY stays in the key ring.
      FIELD_ENCRYPTION_PROVIDER: "kms",
      FIELD_ENCRYPTION_KMS_KEY_ID: fieldEncryptionKmsKey.arn,
      // RDS CA bundle baked into the backend image (T-24-3) for sslmode=verify-full.
      NODE_EXTRA_CA_CERTS: "/app/certs/rds-global-bundle.pem",
      // Only the demo stage may run on mock providers (env.ts PRODUCTION_KEYS guard).
      ALLOW_MOCKS: isDemo ? "true" : "false",
    };
    const kmsPermission = {
      actions: ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey"],
      resources: [fieldEncryptionKmsKey.arn],
    };

    const api = new sst.aws.Service("Api", {
      cluster,
      architecture: "arm64",
      image: backendImage,
      command: ["node", "dist/api/server.js"],
      cpu: "0.5 vCPU",
      memory: "1 GB",
      link: [files],
      permissions: [kmsPermission],
      environment: backendEnvironment,
      ssm: backendSsm,
      loadBalancer: {
        // B-03: HTTPS with an ACM certificate for api.<domain>; plain HTTP only redirects.
        domain: { name: apiHost, dns: sst.aws.dns() },
        rules: [
          { listen: "443/https", forward: "3000/http" },
          { listen: "80/http", redirect: "443/https" },
        ],
        // /readyz checks DB and Redis only (a down imaging or S3 degrades a feature, it must not
        // pull every api task out of the target group).
        health: {
          "3000/http": {
            path: "/readyz",
            interval: "10 seconds",
            timeout: "5 seconds",
            healthyThreshold: 2,
            unhealthyThreshold: 3,
          },
        },
      },
      scaling: {
        min: isProd ? 2 : 1,
        max: isProd ? 6 : 1,
        cpuUtilization: 60,
        requestCount: 1000,
      },
      transform: {
        taskDefinition: withStopTimeout,
        executionRole,
        listener: (args) => {
          if (args.protocol === "HTTPS") args.sslPolicy = "ELBSecurityPolicy-TLS13-1-2-2021-06";
        },
        // Deregister within the drain budget (the ALB default is 300 s).
        target: { deregistrationDelay: 30 },
        loadBalancer: { dropInvalidHeaderFields: true },
      },
    });

    new sst.aws.Service("Worker", {
      cluster,
      architecture: "arm64",
      image: backendImage,
      command: ["node", "dist/worker/index.js"],
      cpu: "1 vCPU",
      memory: "2 GB",
      link: [files],
      permissions: [kmsPermission],
      environment: backendEnvironment,
      ssm: backendSsm,
      scaling: { min: 1, max: 1 },
      transform: { taskDefinition: withStopTimeout, executionRole },
    });

    // One-off release task (wave 24 agreed interface, B-59): bootstrap `invai_app` -> migrate
    // -> reference seed, each an idempotent CLI from T-24-2. It connects as the owner role
    // (MIGRATION_DATABASE_URL) and reads the app role's name and password from DATABASE_URL.
    // Run it before every rollout: `pnpm release:migrate --stage <stage>` (infra/run-migrate.ts).
    const migrate = new sst.aws.Task("Migrate", {
      cluster,
      architecture: "arm64",
      image: backendImage,
      command: [
        "sh",
        "-c",
        "node dist/db/bootstrap-cli.js && node dist/db/migrate-cli.js && node dist/db/reference-seed-cli.js",
      ],
      cpu: "0.5 vCPU",
      memory: "1 GB",
      link: [files],
      permissions: [kmsPermission],
      environment: backendEnvironment,
      ssm: backendSsm,
      dev: false,
      transform: { executionRole },
    });

    // ---- Static sites (CloudFront) -------------------------------------------------------
    // CloudFront serves no CSP by itself, so the viewer-response function adds the same
    // headers vite preview and nginx send (invai-web/invai-floor vite.config.ts `prodCsp`).
    const headersInjection = (csp: $util.Input<string>) =>
      $output(csp).apply((value) => {
        const headers: Record<string, string> = {
          "content-security-policy": value,
          "strict-transport-security": "max-age=31536000; includeSubDomains",
          "x-content-type-options": "nosniff",
          "referrer-policy": "no-referrer",
          "permissions-policy": "camera=(), microphone=(), geolocation=(), payment=()",
        };
        return Object.entries(headers)
          .map(
            ([k, v]) =>
              `event.response.headers[${JSON.stringify(k)}] = { value: ${JSON.stringify(v)} };`,
          )
          .join("\n");
      });
    const prodCsp = (connect: string) =>
      [
        "default-src 'self'",
        "script-src 'self'",
        "style-src 'self' 'unsafe-inline'",
        "img-src 'self' data: blob: https:",
        "font-src 'self'",
        `connect-src ${connect}`,
        "object-src 'none'",
        "base-uri 'none'",
        "frame-ancestors 'none'",
      ].join("; ");

    // ---- WAF (production) ----------------------------------------------------------------
    // B-107 / research 11 §7.1: AWS managed rules plus a per-IP rate rule. Webhooks are exempt
    // from the rate rule (Shopify and EasyPost send from shared IPs) and body-size/XSS body
    // rules only count (webhook and listing bodies are large and contain HTML).
    const wafAcl = (
      name: string,
      scope: "REGIONAL" | "CLOUDFRONT",
      ratePer5Min: number,
      opts?: { provider: aws.Provider },
    ) => {
      const visibility = (metric: string) => ({
        cloudwatchMetricsEnabled: true,
        sampledRequestsEnabled: true,
        metricName: `${name}-${metric}`,
      });
      const managed = (priority: number, group: string, countOnly: string[] = []) => ({
        name: group,
        priority,
        overrideAction: { none: {} },
        statement: {
          managedRuleGroupStatement: {
            vendorName: "AWS",
            name: group,
            ruleActionOverrides: countOnly.map((rule) => ({
              name: rule,
              actionToUse: { count: {} },
            })),
          },
        },
        visibilityConfig: visibility(group),
      });
      return new aws.wafv2.WebAcl(
        name,
        {
          scope,
          defaultAction: { allow: {} },
          visibilityConfig: visibility("all"),
          rules: [
            {
              name: "RatePerIp",
              priority: 0,
              action: { block: {} },
              statement: {
                rateBasedStatement: {
                  limit: ratePer5Min,
                  aggregateKeyType: "IP",
                  scopeDownStatement: {
                    notStatement: {
                      statements: [
                        {
                          byteMatchStatement: {
                            searchString: "/webhooks/",
                            positionalConstraint: "STARTS_WITH",
                            fieldToMatch: { uriPath: {} },
                            textTransformations: [{ priority: 0, type: "NONE" }],
                          },
                        },
                      ],
                    },
                  },
                },
              },
              visibilityConfig: visibility("rate"),
            },
            managed(1, "AWSManagedRulesAmazonIpReputationList"),
            managed(2, "AWSManagedRulesCommonRuleSet", [
              "SizeRestrictions_BODY",
              "CrossSiteScripting_BODY",
            ]),
            managed(3, "AWSManagedRulesKnownBadInputsRuleSet"),
          ],
        },
        opts,
      );
    };

    let cdnWebAclArn: $util.Output<string> | undefined;
    if (isProd) {
      const apiAcl = wafAcl("ApiWaf", "REGIONAL", 20_000);
      new aws.wafv2.WebAclAssociation("ApiWafAssociation", {
        resourceArn: api.nodes.loadBalancer.arn,
        webAclArn: apiAcl.arn,
      });
      // CloudFront web ACLs must live in us-east-1, whatever the stage's region.
      const usEast1 = new aws.Provider("UsEast1", { region: "us-east-1" });
      cdnWebAclArn = wafAcl("CdnWaf", "CLOUDFRONT", 5_000, { provider: usEast1 }).arn;
    }

    const web = new sst.aws.StaticSite("Web", {
      path: "../invai-web",
      build: { command: "pnpm build", output: "dist" },
      domain: webHost,
      environment: { VITE_API_URL: apiOrigin, VITE_S3_ORIGIN: s3Origin },
      edge: {
        viewerResponse: {
          injection: headersInjection(
            s3Origin.apply((s3) =>
              prodCsp(
                webCsp.connectSrc(webCsp.requireApiOrigin(apiOrigin), webCsp.uploadOrigin(s3)),
              ),
            ),
          ),
        },
      },
      transform: cdnWebAclArn ? { cdn: { webAclArn: cdnWebAclArn } } : undefined,
    });

    const floor = new sst.aws.StaticSite("Floor", {
      path: "../invai-floor",
      build: { command: "pnpm build", output: "dist" },
      domain: floorHost,
      environment: { VITE_API_URL: apiOrigin },
      edge: {
        viewerResponse: {
          injection: headersInjection(
            prodCsp(floorCsp.connectSrc(floorCsp.requireApiOrigin(apiOrigin))),
          ),
        },
      },
      transform: cdnWebAclArn ? { cdn: { webAclArn: cdnWebAclArn } } : undefined,
    });

    return {
      api: apiOrigin,
      web: web.url,
      floor: floor.url,
      imaging: imagingUrl,
      migrateTask: migrate.nodes.taskDefinition.arn,
    };
  },
});
